     1	import { esc } from './escape.js';
     2	
     3	const TONES = new Set(['ok', 'warn', 'bad', 'info', 'muted']);
     4	
     5	/**
     6	 * Status chip. Map your domain's states to a tone at the call site.
     7	 *
     8	 * @param {string} label
     9	 * @param {'ok' | 'warn' | 'bad' | 'info' | 'muted'} [tone]
    10	 * @returns {string}
    11	 */
    12	export function statusChip(label, tone = 'muted') {
    13	  const t = TONES.has(tone) ? tone : 'muted';
    14	  return `<span class="ui-chip ui-chip--${t}">${esc(label)}</span>`;
    15	}
=== src/ui/empty-state.js
     1	import { esc } from './escape.js';
     2	
     3	/**
     4	 * Placeholder for a list or panel with nothing to show.
     5	 *
     6	 * @param {{title: string, body?: string}} opts `body` is trusted HTML.
     7	 * @returns {string}
     8	 */
     9	export function emptyState({ title, body = '' }) {
    10	  const more = body ? `<div class="ui-empty__body">${body}</div>` : '';
    11	  return `<div class="ui-empty"><p class="ui-empty__title">${esc(title)}</p>${more}</div>`;
    12	}
=== src/ui/escape.js
     1	// Escapes text for HTML element content and quoted attribute values.
     2	export function esc(value) {
     3	  return String(value ?? '')
     4	    .replaceAll('&', '&amp;')
     5	    .replaceAll('<', '&lt;')
     6	    .replaceAll('>', '&gt;')
     7	    .replaceAll('"', '&quot;')
     8	    .replaceAll("'", '&#39;');
     9	}
=== src/ui/filter-bar.js
     1	import { esc } from './escape.js';
     2	
     3	/**
     4	 * A GET form for a page's filters. `fields` is trusted HTML, usually
     5	 * `selectField` output; public/harbor.js submits the form when a field marked
     6	 * `data-autosubmit` changes. `keep` carries query state the bar should not
     7	 * drop, such as the current sort.
     8	 *
     9	 * @param {object} opts
    10	 * @param {string} opts.action
    11	 * @param {string[]} opts.fields
    12	 * @param {Record<string, string | undefined>} [opts.keep]
    13	 * @returns {string}
    14	 */
    15	export function filterBar({ action, fields, keep = {} }) {
    16	  const hidden = Object.entries(keep)
    17	    .filter(([, v]) => v !== undefined && v !== '')
    18	    .map(([k, v]) => `<input type="hidden" name="${esc(k)}" value="${esc(v)}">`)
    19	    .join('');
    20	  return `<form class="ui-filter-bar" method="get" action="${esc(action)}">${fields.join('')}${hidden}</form>`;
    21	}
